ST.xhtml:
// === 🔀 §1 ARBITRAGE DES MODES MACHINE & INTENTION OPÉRATEUR ===
{region "§1 Modes machine"}

instModes(
    Enable                  := TRUE,
    Reset                   := GVL_IHM.Modes.Cmd.BtnModeReset,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    SelMode                 := GVL_IHM.Modes.Cmd.SelMode,
    SelSyncEnable           := GVL_IHM.M1M2Sync.Cmd.SelSyncEnable,
    InhibitM1Request        := GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit,
    InhibitM2Request        := GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit,
    SelHomingApproachEnable := GVL_IHM.Commun.Cfg.SelHomingApproachEnable,
    EncoderFaultPresent     := (PRG_02_Acquisition.HwIn.Winch.COD1_DeviceState <> DEVICE_STATE.RUNNING) OR (PRG_02_Acquisition.HwIn.Winch.COD2_DeviceState <> DEVICE_STATE.RUNNING),
    JoystickWinchSelectRequest := GVL_IHM.Modes.Cmd.SelJoystickWinch,
    SelMaintenanceZoneAccess := GVL_IHM.TranslationM3.Cmd.TglMaintenanceZoneAccess,
    // Arrêt mécanique confirmé des treuils (condition de bascule N1/N2, AF-05 §4bis)
    M1ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    M1BrakeIsOpen             := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    M1SpeedAbsMps             := PRG_02_Acquisition.Data.Encoders.M1.Speed_Mps,
    M2ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    M2BrakeIsOpen             := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    M2SpeedAbsMps             := PRG_02_Acquisition.Data.Encoders.M2.Speed_Mps,
    // États homing (levée du re-homing obligatoire)
    M1HomingDone              := PRG_02_Acquisition.Data.EncoderM1.Measurement.HomingLifecycle.Done,
    M1Homed                   := PRG_02_Acquisition.Data.EncoderM1.Homed,
    M1HomingSuspect           := PRG_02_Acquisition.Data.EncoderM1.HomingSuspect,
    M2HomingDone              := PRG_02_Acquisition.Data.EncoderM2.Measurement.HomingLifecycle.Done,
    M2Homed                   := PRG_02_Acquisition.Data.EncoderM2.Homed,
    M2HomingSuspect           := PRG_02_Acquisition.Data.EncoderM2.HomingSuspect,
    // Usage effectif d'un override/bypass de position (producteur PRG_04, lag 1 scan
    // assumé : PRG_04 est de rang 04, ce programme de rang 03)
    M1PositionLimitOverridden := PRG_04_Treuils_Benne.Data.PositionLimitOverriddenM1,
    M2PositionLimitOverridden := PRG_04_Treuils_Benne.Data.PositionLimitOverriddenM2,
    MachineReferenceReady     := PRG_02_Acquisition.MachineReferenceReady,
    // Restauration boot des drapeaux de re-homing (miroir PERSISTENT)
    BootHomingRequiredM1      := GVL_PERSISTENT._MaintM1HomingRequired,
    BootHomingRequiredM2      := GVL_PERSISTENT._MaintM2HomingRequired
);

// Miroir persistant du re-homing obligatoire (pattern FB_MirrorBypassRetain) :
// FB_Modes est le producteur unique de la décision ; GVL_PERSISTENT n'est que la mémoire.
GVL_PERSISTENT._MaintM1HomingRequired := instModes.Auth.HomingRequiredM1;
GVL_PERSISTENT._MaintM2HomingRequired := instModes.Auth.HomingRequiredM2;

// Qualification de l'intention opérateur couplée (M1+M2) dans le même scan
IF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
    CoupledUserRequestDirection := PRG_02_Acquisition.Data.Joystick.AxisY.Direction;
    CoupledUserRequestActive := PRG_02_Acquisition.HwIn.Operator.JoyBtnRaw
                                     AND (instModes.Auth.JoystickWinchSelectArbitrated = 0);
ELSE
    IF GVL_IHM.Commun.BtnWinchBothUp THEN
        CoupledUserRequestDirection := 1;
    ELSIF GVL_IHM.Commun.BtnWinchBothDown THEN
        CoupledUserRequestDirection := -1;
    ELSE
        CoupledUserRequestDirection := 0;
    END_IF;
    CoupledUserRequestActive := (CoupledUserRequestDirection <> 0);
END_IF;

{endregion}


// === 🤿 §2 ASSISTANTS DE DRAGAGE (PLONGÉE & EXTRACTION) ===
{region "§2 Assistants de dragage"}

// 1. Garde-clear de la confirmation manuelle et bypass fond touché
IF NOT (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
   OR NOT PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI
   OR PRG_07_Supervision.FaultMachineReset_IHM
   OR (CoupledUserRequestActive AND (CoupledUserRequestDirection = -1)) THEN
    GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed := FALSE;
    BypassKoboldBottomTouched := FALSE;
END_IF;
ManualBottomPositionConfirmed := GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed;

// 2. Détection front descendant Kobold sous bypass
BypassKoboldFallEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);
IF GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
   AND CoupledUserRequestActive AND (CoupledUserRequestDirection = -1)
   AND BypassKoboldFallEdge.Q THEN
    BypassKoboldBottomTouched := TRUE;
END_IF;

// 3. Instance FB_DiveSearch (Recherche de fond Kobold)
instDiveSearch(
    Enable := (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.DredgingAssist.Cmd.TglEnableDiveSearch,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode := instModes.Auth.Mode,
    MotionRequestActive := CoupledUserRequestActive,
    MotionDirection := CoupledUserRequestDirection,
    BucketIsOpen := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen,
    KoboldImmersed := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI,
    M1Position_M := PRG_02_Acquisition.Data.Encoders.M1.CablePosM,
    M2Position_M := PRG_02_Acquisition.Data.Encoders.M2.CablePosM,
    PositionsValid := NOT PRG_02_Acquisition.Data.M1_EncoderFault
                       AND NOT PRG_02_Acquisition.Data.M2_EncoderFault,
    // Palier actuel M1 reellement commande (public PRG_04 §8). PRG_03 est de rang 03,
    // PRG_04 de rang 04 : lecture du scan PRECEDENT (lag 1 scan assume, meme pratique que
    // le reste de PRG_03). Rend effectif le refus interne du Palier 5 en plongee Kobold.
    CurrentSpeedStep := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber,
    DiveStartMin_M := GVL_IHM.DredgingAssist.Cfg.DiveStartMin_M,
    ImmersionUpper_M := GVL_IHM.DredgingAssist.Cfg.ImmersionUpper_M,
    ImmersionLower_M := GVL_IHM.DredgingAssist.Cfg.ImmersionLower_M,
    CableLimitAscent_M := GVL_IHM.Commun.Cfg.CfgCableLimitAscent_M,
    LimitLegalDepthMin_M := GVL_IHM.Commun.Cfg.LimitLegalDepthMinAllowed_M,
    CycleTime := T#10ms,
    BypassPreconditions := GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
);

// Synthèse de confirmation fond
BottomPositionConfirmed := instDiveSearch.BottomTouchConfirmed OR ManualBottomPositionConfirmed OR BypassKoboldBottomTouched;

// 4. Instance FB_ExtractionSequence (Fermeture et décollage assisté)
instExtractionSequence(
    Enable := (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.DredgingAssist.Cmd.TglEnableExtractionSequence,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode := instModes.Auth.Mode,
    MotionRequestActive := CoupledUserRequestActive,
    MotionDirection := CoupledUserRequestDirection,
    BottomPositionConfirmed := BottomPositionConfirmed,
    BucketIsClosed := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsClosed,
    BucketBusy := PRG_04_Treuils_Benne.Data.BucketBusy,
    BucketError := PRG_04_Treuils_Benne.Data.BucketError,
    WinchSyncError := PRG_04_Treuils_Benne.Data.WinchSyncError,
    M1Position_M := PRG_02_Acquisition.Data.Encoders.M1.CablePosM,
    M2Position_M := PRG_02_Acquisition.Data.Encoders.M2.CablePosM,
    M1MeasuredSpeedValid := PRG_02_Acquisition.Data.Encoders.M1.SpeedValid,
    M2MeasuredSpeedValid := PRG_02_Acquisition.Data.Encoders.M2.SpeedValid,
    PositionsValid := NOT PRG_02_Acquisition.Data.M1_EncoderFault
                       AND NOT PRG_02_Acquisition.Data.M2_EncoderFault,
    ControlAscentDistance_M := GVL_IHM.DredgingAssist.Cfg.ExtractionControlDistance_M,
    CfgBucketCloseTimeout := T#75s,
    BucketMoveTimeout := GVL_IHM.M2TreuilBenne.Bucket.Cfg.CfgTimeoutDuration,
    CycleTime := T#10ms
);

IF instExtractionSequence.BottomConfirmationConsumed THEN
    GVL_IHM.DredgingAssist.Cmd.TglBucketAtBottomConfirmed := FALSE;
END_IF;

{endregion}


// === 🔄 §3 SÉQUENCEUR DE CYCLE SEMI-AUTOMATIQUE ===
{region "§3 Séquenceur de cycle"}
// 🕹️ CycleMotionPermit = manche défléchi (non centré) — D2
// ⚠️ Entrées consommées sur les bus publics Data (retard N-1 admis AF-02) :

instCycleSemiAuto(
    Enable                  := (instModes.Auth.Mode = E_Mode.SEMI_AUTO),
    Reset                   := GVL_IHM.Cycle.Cmd.BtnReset,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := instModes.Auth.Mode,
    CycleMotionPermit       := NOT PRG_02_Acquisition.Data.Joystick.AtNeutralXY,
    DeadmanArmed            := PRG_02_Acquisition.Data.JoystickDeadmanArmed,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    StartCycle              := GVL_IHM.Cycle.Cmd.BtnStart,
    AbortCycle              := GVL_IHM.Cycle.Cmd.BtnAbort,
    SelTarget               := GVL_IHM.TranslationM3.Cmd.SelTarget,
    SetDepthM               := GVL_IHM.Cycle.Cfg.SetDepth_M,
    SetOffsetM              := GVL_IHM.Cycle.Cfg.SetOffset_M,
    KoboldContactFond       := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI,
    LimitLegalReached       := GVL_IHM.Commun.LimitLegalReached,
    LimitLegalDepthM        := _CommunCfgPersist.LimitLegalDepthMinAllowed_M,
    WinchSyncError          := PRG_04_Treuils_Benne.Data.WinchSyncError,
    WinchSyncDeltaM         := PRG_04_Treuils_Benne.Data.WinchSyncSignedDeltaPosM,
    M1_CablePosM            := PRG_02_Acquisition.Data.Encoders.M1.CablePosM,
    M2_CablePosM            := PRG_02_Acquisition.Data.Encoders.M2.CablePosM,
    M1_MeasuredSpeedMps     := PRG_02_Acquisition.Data.Encoders.M1.Speed_Mps,
    M2_MeasuredSpeedMps     := PRG_02_Acquisition.Data.Encoders.M2.Speed_Mps,
    SpeedMismatchThresholdMps := 1.5,   // Seuil écart vitesse M1/M2 (revue : ~1-2 m/s, retenu 1.5)
    SpeedMismatchTimeout    := T#500ms, // Tempo confirmation écart vitesse (revue)
    CableLimitM1AscentM     := _CommunCfgPersist.CfgCableLimitAscent_M,
    Translation_At_P1       := PRG_05_Translation.Data.M3_AtP1Stable,
    Translation_At_Tremie   := PRG_05_Translation.Data.M3_AtTremieStable,
    Translation_At_Maintenance := PRG_05_Translation.Data.M3_AtMaintenanceStable,
    Translation_Busy        := PRG_05_Translation.Data.TranslationBusy,
    Translation_Done        := PRG_05_Translation.Data.TranslationDone,
    Benne_Busy              := PRG_04_Treuils_Benne.Data.BucketBusy,
    Benne_Done              := PRG_04_Treuils_Benne.Data.BucketDone,
    Benne_IsOpen            := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen,
    Benne_IsClosed          := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsClosed,
    Benne_IsRoughlyClosed   := PRG_04_Treuils_Benne.Data.Benne_IsRoughlyClosed,  // Tolérance matière 2m
    HomedM1                 := PRG_02_Acquisition.Data.EncoderM1.Homed,
    HomedM2                 := PRG_02_Acquisition.Data.EncoderM2.Homed,
    TopPositionSensor       := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    HomingRequest           := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome OR GVL_IHM.M2TreuilBenne.Cmd.BtnHome,
    SampleCount            := _CycleSampleCount
);

{endregion}


// === 📤 §4 PUBLICATION DU BUS INTER-PRG & AUTORISATIONS ===
{region "§4 Publication bus public"}

// 1. Autorisations machine
Data.Auth := instModes.Auth;
// 1bis. Défauts de l'arbitre de mode (refus Semi-Auto, changement de mode refusé) —
// publiés pour que l'IHM les affiche : un interlock invisible est un interlock contourné.
Data.ModesFault := instModes.Fault;

// 1bis. Intention couplée continue opérateur (inconditionnelle, TOUS modes)
Data.ReqProgram.OperatorCoupledIntent.Active    := CoupledUserRequestActive;
Data.ReqProgram.OperatorCoupledIntent.Direction := CoupledUserRequestDirection;

// 2. Demandes programme et état public de séquence
IF instModes.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Demandes treuils M1 / M2
    Data.ReqProgram.ReqWinchM1.ReqStartStop := instCycleSemiAuto.WinchM1Cmd.StartStop;
    Data.ReqProgram.ReqWinchM1.ReqDirection := instCycleSemiAuto.WinchM1Cmd.Direction;
    Data.ReqProgram.ReqWinchM1.SpeedTgtPct  := instCycleSemiAuto.WinchM1Cmd.SpeedPct;

    Data.ReqProgram.ReqWinchM2.ReqStartStop := instCycleSemiAuto.WinchM2Cmd.StartStop;
    Data.ReqProgram.ReqWinchM2.ReqDirection := instCycleSemiAuto.WinchM2Cmd.Direction;
    Data.ReqProgram.ReqWinchM2.SpeedTgtPct  := instCycleSemiAuto.WinchM2Cmd.SpeedPct;

    // Demande translation M3
    Data.ReqProgram.ReqTranslation.ReqStart    := instCycleSemiAuto.TranslationCmd.Start;
    Data.ReqProgram.ReqTranslation.PositionTgt := instCycleSemiAuto.TranslationCmd.Target;

    // Demande benne
    Data.ReqProgram.ReqBucket.ReqOpen                     := instCycleSemiAuto.BucketCmd.Open;
    Data.ReqProgram.ReqBucket.ReqClose                    := instCycleSemiAuto.BucketCmd.Close;
    Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable      := instCycleSemiAuto.BucketCmd.KoboldContactorCmd;
    Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen := TRUE;
    Data.ReqProgram.ReqBucket.ExtractionControlActive     := FALSE;
    // SEMI_AUTO : aucun assistant de plongee actif -> plancher neutre (0 = aucun).
    Data.ReqProgram.ReqBucket.MinStepDown                 := 0;

    // État séquence active
    IF instCycleSemiAuto.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId := E_ProgramSequence.MAIN_CYCLE;
    ELSE
        Data.SequenceState.SequenceId := E_ProgramSequence.NONE;
    END_IF;

    Data.SequenceState.Ready                  := instCycleSemiAuto.Ready;
    Data.SequenceState.Lifecycle              := instCycleSemiAuto.Lifecycle;
    Data.SequenceState.Fault                  := instCycleSemiAuto.Fault;
    Data.SequenceState.Step                   := instCycleSemiAuto.CycleStep;
    Data.SequenceState.StepStr                := instCycleSemiAuto.CycleStateStr;
    Data.SequenceState.StepAtFault            := instCycleSemiAuto.CycleStepAtError;
    Data.SequenceState.OperatorActionId       := instCycleSemiAuto.OperatorActionId;
    Data.SequenceState.OperatorAction         := instCycleSemiAuto.OperatorAction;
    Data.SequenceState.ExpectedAxis           := instCycleSemiAuto.ExpectedAxis;
    Data.SequenceState.ExpectedDirection      := instCycleSemiAuto.ExpectedDirection;
    Data.SequenceState.WaitingForOperator     := instCycleSemiAuto.WaitingForOperator;
    Data.SequenceState.WaitingForProcess      := instCycleSemiAuto.WaitingForProcess;
    Data.SequenceState.RequestActive          := instCycleSemiAuto.RequestActive;
    Data.SequenceState.SpeedMismatchMps       := instCycleSemiAuto.SpeedMismatchMps;
    Data.SequenceState.SpeedMismatchActive    := instCycleSemiAuto.SpeedMismatchActive;
    Data.SequenceState.SpeedMismatchConfirmed := instCycleSemiAuto.SpeedMismatchConfirmed;
    Data.SequenceState.DiveState              := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.DiveStepAtFault        := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.BottomTouchConfirmed   := FALSE;
    Data.SequenceState.ExtractionState        := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.ExtractionStepAtFault  := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;

    // === RESET ÉTATS ASSISTANTS (neutralisation déterministe au passage SEMI_AUTO) ===
    // Aucun assistant de dragage n'est actif en SEMI_AUTO : mêmes valeurs neutres que la branche DISABLE.
    Data.SequenceState.DiveReady                  := FALSE;
    Data.SequenceState.DiveBusy                   := FALSE;
    Data.SequenceState.DiveDone                   := FALSE;
    Data.SequenceState.DiveError                  := FALSE;
    Data.SequenceState.DiveErrorId                := 0;
    Data.SequenceState.ExtractionReady             := FALSE;
    Data.SequenceState.ExtractionBusy              := FALSE;
    Data.SequenceState.ExtractionDone              := FALSE;
    Data.SequenceState.ExtractionError             := FALSE;
    Data.SequenceState.ExtractionErrorId           := 0;
    Data.SequenceState.DumpAtTremieArmed           := FALSE;
    Data.SequenceState.DumpAtTremieAssistActive      := FALSE;
    Data.SequenceState.DumpAtTremieAtTremie          := FALSE;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := FALSE;
    Data.SequenceState.DumpAtTremieDescentLocked     := FALSE;
    Data.SequenceState.BypassDiveActive            := FALSE;
    Data.SequenceState.BypassKoboldBottomTouched   := FALSE;

ELSIF (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2) THEN
    // Mode Manuel / Maintenance : Publication des requêtes issues des assistants
    Data.ReqProgram.ReqWinchM1.ReqStartStop := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqDirection := 0;
    Data.ReqProgram.ReqWinchM1.SpeedTgtPct  := 0.0;

    Data.ReqProgram.ReqWinchM2.ReqStartStop := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqDirection := 0;
    Data.ReqProgram.ReqWinchM2.SpeedTgtPct  := 0.0;

    Data.ReqProgram.ReqTranslation.ReqStart    := FALSE;
    Data.ReqProgram.ReqTranslation.PositionTgt := 0;

    // Requêtes benne et assistants
    DumpAtTremieActive := GVL_IHM.DredgingAssist.Cmd.TglEnableDumpAtTremie;
    DumpAtTremieAssistActive := DumpAtTremieActive;
    DumpAtTremieBucketOpenArmed := DumpAtTremieAssistActive AND PRG_05_Translation.Data.M3_AtTremieStable;

    Data.ReqProgram.ReqBucket.ReqOpen                     := DumpAtTremieBucketOpenArmed;
    Data.ReqProgram.ReqBucket.ReqClose                    := instExtractionSequence.BucketCloseRequest;
    Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable      := instDiveSearch.KoboldMeasureEnable
                                                            OR (GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence
                                                                AND CoupledUserRequestActive AND (CoupledUserRequestDirection = -1));
    Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen := NOT (instDiveSearch.Enable AND CoupledUserRequestActive
                                                                AND (CoupledUserRequestDirection = -1)
                                                                AND NOT PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen);
    Data.ReqProgram.ReqBucket.ExtractionControlActive     := instExtractionSequence.ExtractionControlActive;
    // Plancher de plongee : produit par FB_DiveSearch, consomme par PRG_04 §5ter.
    Data.ReqProgram.ReqBucket.MinStepDown                 := instDiveSearch.MinStepDown;

    // États de séquence
    IF instDiveSearch.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId        := E_ProgramSequence.DIVE_SEARCH;
        Data.SequenceState.OperatorActionId  := instDiveSearch.OperatorActionId;
        Data.SequenceState.OperatorAction    := instDiveSearch.OperatorAction;
    ELSIF instExtractionSequence.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId        := E_ProgramSequence.EXTRACTION;
        Data.SequenceState.OperatorActionId  := instExtractionSequence.OperatorActionId;
        Data.SequenceState.OperatorAction    := instExtractionSequence.OperatorAction;
    ELSE
        Data.SequenceState.SequenceId        := E_ProgramSequence.NONE;
        Data.SequenceState.OperatorActionId  := 0;
        Data.SequenceState.OperatorAction    := '';
    END_IF;

    Data.SequenceState.Ready                  := instDiveSearch.Ready OR instExtractionSequence.Ready;
    Data.SequenceState.Lifecycle.Busy         := instDiveSearch.Lifecycle.Busy OR instExtractionSequence.Lifecycle.Busy;
    Data.SequenceState.Lifecycle.Done         := instDiveSearch.Lifecycle.Done OR instExtractionSequence.Lifecycle.Done;
    Data.SequenceState.Fault.Error            := instDiveSearch.Fault.Error OR instExtractionSequence.Fault.Error;
    IF instDiveSearch.Fault.Error THEN
        Data.SequenceState.Fault.ErrorId      := instDiveSearch.Fault.ErrorId;
        Data.SequenceState.Fault.Latched      := instDiveSearch.Fault.Latched;
    ELSIF instExtractionSequence.Fault.Error THEN
        Data.SequenceState.Fault.ErrorId      := instExtractionSequence.Fault.ErrorId;
        Data.SequenceState.Fault.Latched      := instExtractionSequence.Fault.Latched;
    ELSE
        Data.SequenceState.Fault.ErrorId      := 0;
        Data.SequenceState.Fault.Latched      := FALSE;
    END_IF;
    Data.SequenceState.Step                   := E_CycleStep.X0_PREPARATION;
    Data.SequenceState.StepStr                := 'ASSIST_MODE';
    Data.SequenceState.StepAtFault            := E_CycleStep.X0_PREPARATION;
    Data.SequenceState.ExpectedAxis           := E_OperatorAxis.JOYSTICK_Y;
    Data.SequenceState.ExpectedDirection      := CoupledUserRequestDirection;
    Data.SequenceState.WaitingForOperator     := FALSE;
    Data.SequenceState.WaitingForProcess      := FALSE;
    Data.SequenceState.RequestActive          := CoupledUserRequestActive;
    Data.SequenceState.SpeedMismatchMps       := 0.0;
    Data.SequenceState.SpeedMismatchActive    := FALSE;
    Data.SequenceState.SpeedMismatchConfirmed := FALSE;
    Data.SequenceState.DiveReady                  := instDiveSearch.Ready;
    Data.SequenceState.DiveBusy                   := instDiveSearch.Lifecycle.Busy;
    Data.SequenceState.DiveDone                   := instDiveSearch.Lifecycle.Done;
    Data.SequenceState.DiveError                  := instDiveSearch.Fault.Error;
    Data.SequenceState.DiveErrorId                := instDiveSearch.Fault.ErrorId;
    Data.SequenceState.DiveState                  := instDiveSearch.DiveState;
    Data.SequenceState.DiveStepAtFault             := instDiveSearch.StepAtFault;
    Data.SequenceState.BottomTouchConfirmed       := BottomPositionConfirmed;
    Data.SequenceState.ExtractionReady             := instExtractionSequence.Ready;
    Data.SequenceState.ExtractionBusy              := instExtractionSequence.Lifecycle.Busy;
    Data.SequenceState.ExtractionDone              := instExtractionSequence.Lifecycle.Done;
    Data.SequenceState.ExtractionError             := instExtractionSequence.Fault.Error;
    Data.SequenceState.ExtractionErrorId           := instExtractionSequence.Fault.ErrorId;
    Data.SequenceState.ExtractionState             := instExtractionSequence.ExtractionState;
    Data.SequenceState.ExtractionStepAtFault       := instExtractionSequence.StepAtFault;
    Data.SequenceState.DumpAtTremieArmed           := DumpAtTremieActive;
    Data.SequenceState.DumpAtTremieAssistActive      := DumpAtTremieAssistActive;
    Data.SequenceState.DumpAtTremieAtTremie          := PRG_05_Translation.Data.M3_AtTremieStable;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := DumpAtTremieBucketOpenArmed;
    Data.SequenceState.DumpAtTremieDescentLocked     := DumpAtTremieAssistActive AND NOT (PRG_05_Translation.Data.M3_AtP1Stable OR PRG_05_Translation.Data.M3_AtMaintenanceStable);
    Data.SequenceState.BypassDiveActive            := GVL_IHM.DredgingAssist.Cmd.TglBypassDiveSearchSequence;
    Data.SequenceState.BypassKoboldBottomTouched   := BypassKoboldBottomTouched;

ELSE
    // Neutralisation déterministe (DISABLE)
    Data.ReqProgram.ReqWinchM1.ReqStartStop := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqDirection := 0;
    Data.ReqProgram.ReqWinchM1.SpeedTgtPct  := 0.0;

    Data.ReqProgram.ReqWinchM2.ReqStartStop := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqDirection := 0;
    Data.ReqProgram.ReqWinchM2.SpeedTgtPct  := 0.0;

    Data.ReqProgram.ReqTranslation.ReqStart    := FALSE;
    Data.ReqProgram.ReqTranslation.PositionTgt := 0;

    Data.ReqProgram.ReqBucket.ReqOpen                     := FALSE;
    Data.ReqProgram.ReqBucket.ReqClose                    := FALSE;
    Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable      := FALSE;
    Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen := TRUE;
    Data.ReqProgram.ReqBucket.ExtractionControlActive     := FALSE;
    // DISABLE : plancher neutre (0 = aucun).
    Data.ReqProgram.ReqBucket.MinStepDown                 := 0;

    Data.SequenceState.SequenceId              := E_ProgramSequence.NONE;
    Data.SequenceState.Ready                   := FALSE;
    Data.SequenceState.Lifecycle.Busy          := FALSE;
    Data.SequenceState.Lifecycle.Done          := FALSE;
    Data.SequenceState.Fault.Error             := FALSE;
    Data.SequenceState.Fault.ErrorId           := 0;
    Data.SequenceState.Fault.Latched           := FALSE;
    Data.SequenceState.Step                    := E_CycleStep.X0_PREPARATION;
    Data.SequenceState.StepStr                 := 'X0_PREPARATION';
    Data.SequenceState.StepAtFault             := E_CycleStep.X0_PREPARATION;
    Data.SequenceState.OperatorActionId        := 0;
    Data.SequenceState.OperatorAction          := '';
    Data.SequenceState.ExpectedAxis            := E_OperatorAxis.NONE;
    Data.SequenceState.ExpectedDirection       := 0;
    Data.SequenceState.WaitingForOperator      := FALSE;
    Data.SequenceState.WaitingForProcess       := FALSE;
    Data.SequenceState.RequestActive           := FALSE;
    Data.SequenceState.SpeedMismatchMps        := 0.0;
    Data.SequenceState.SpeedMismatchActive     := FALSE;
    Data.SequenceState.SpeedMismatchConfirmed  := FALSE;
    Data.SequenceState.DiveReady                  := FALSE;
    Data.SequenceState.DiveBusy                   := FALSE;
    Data.SequenceState.DiveDone                   := FALSE;
    Data.SequenceState.DiveError                  := FALSE;
    Data.SequenceState.DiveErrorId                := 0;
    Data.SequenceState.DiveState                  := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.DiveStepAtFault            := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.BottomTouchConfirmed       := FALSE;
    Data.SequenceState.ExtractionReady             := FALSE;
    Data.SequenceState.ExtractionBusy              := FALSE;
    Data.SequenceState.ExtractionDone              := FALSE;
    Data.SequenceState.ExtractionError             := FALSE;
    Data.SequenceState.ExtractionErrorId           := 0;
    Data.SequenceState.ExtractionState             := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.ExtractionStepAtFault       := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.DumpAtTremieArmed           := FALSE;
    Data.SequenceState.DumpAtTremieAssistActive      := FALSE;
    Data.SequenceState.DumpAtTremieAtTremie          := FALSE;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := FALSE;
    Data.SequenceState.DumpAtTremieDescentLocked     := FALSE;
    Data.SequenceState.BypassDiveActive            := FALSE;
    Data.SequenceState.BypassKoboldBottomTouched   := FALSE;
END_IF;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut"}
// 🔑 1. FRONTS ET CAUSES
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
DeadmanArmedEdge(CLK := DeadmanArmed);
AbortEdge(CLK := AbortCycle);
EnableEdge(CLK := Enable);

// ⏱️ Surveillance indépendante de la remontée lente
StabilizationTimer(IN := (State = E_CycleStep.X7_CTRL_ASCENT), PT := CtrlAscentTimeout);

// 📏 Comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.X7_CTRL_ASCENT)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// Tempo max d'étape (R5) — lancée SEULEMENT si pilotage joystick actif (pas de défaut au repos)
StepMaxTimer(IN := CycleMotionPermit AND (State <> E_CycleStep.X0_PREPARATION)
                  AND (State <> E_CycleStep.X13_DONE_SYNC)
                  AND (State <> E_CycleStep.STABILIZING),
             PT := StepMaxTimeout);

// Table des causes de défaut
instCauses[0].Active   := LimitLegalReached AND (State = E_CycleStep.X4_DESCEND_OPEN);
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Limite legale de profondeur atteinte pendant descente';

instCauses[1].Active   := WinchSyncError AND (State <> E_CycleStep.X0_PREPARATION) AND (State <> E_CycleStep.STABILIZING);
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Desynchronisme treuils M1/M2 bloquant';

instCauses[2].Active   := SpeedMismatchConfirmed AND (State <> E_CycleStep.X0_PREPARATION) AND (State <> E_CycleStep.STABILIZING);
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Ecart de vitesse M1/M2 confirme en montee';

instCauses[3].Active   := NOT HeartbeatIhmOk AND (State <> E_CycleStep.X0_PREPARATION) AND (State <> E_CycleStep.STABILIZING);
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Perte communication IHM pendant cycle';

instCauses[4].Active   := StepMaxTimer.Q AND (State <> E_CycleStep.STABILIZING);
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement tempo maximale d etape (blocage mouvement)';

instCauses[5].Active   := (StabilizationTimer.Q OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM))
                          AND (State = E_CycleStep.X7_CTRL_ASCENT);
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Defaut de stabilisation / tolerance ecart codeurs en remontee controle';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
ErrorEdge(CLK := Fault.Error);
{endregion}

{region "§2 Gate securite & Bascule Mode"}
// 🛑 2. GATES DE SÉCURITÉ ET NEUTRALISATION
IF NOT Enable OR NOT PowerContactorEngaged THEN
    WinchM1Cmd.StartStop   := FALSE;
    WinchM1Cmd.Direction   := 0;
    WinchM1Cmd.SpeedPct    := 0.0;

    WinchM2Cmd.StartStop   := FALSE;
    WinchM2Cmd.Direction   := 0;
    WinchM2Cmd.SpeedPct    := 0.0;

    TranslationCmd.Start   := FALSE;
    TranslationCmd.Target  := 0;

    BucketCmd.Open         := FALSE;
    BucketCmd.Close        := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;

    // Si on quitte le semi-auto alors qu'un cycle était en cours, on mémorise l'étape pour la pause
    IF (State <> E_CycleStep.X0_PREPARATION) AND (State <> E_CycleStep.X13_DONE_SYNC) AND (State <> E_CycleStep.STABILIZING) THEN
        PausedState := State;
        WaitingResume := TRUE;
    END_IF;

    CycleStep            := State;
    CycleStateStr        := 'Cycle desactive : securite absente ou mode hors semi-auto';
    Ready                := FALSE;
    Lifecycle.Busy       := FALSE;
    Lifecycle.Done       := FALSE;
    SpeedMismatchTimer(IN := FALSE, PT := SpeedMismatchTimeout);
    SpeedMismatchMps := 0.0;
    SpeedMismatchActive := FALSE;
    SpeedMismatchConfirmed := FALSE;
    OperatorActionId := 0;
    OperatorAction := 'Passer en mode Semi-Auto et engager la securite pour activer le cycle.';
    ExpectedAxis := E_OperatorAxis.NONE;
    ExpectedDirection := 0;
    WaitingForOperator := FALSE;
    WaitingForProcess := FALSE;
    RequestActive := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;

// Au retour en Semi-Auto (front montant Enable), si une étape était en cours, on exige une reprise consciente
IF EnableEdge.Q AND WaitingResume THEN
    // Sécurité anti-redémarrage automatique : reste en attente de StartCycle
    ;
END_IF;

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers STABILIZING
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
    State := E_CycleStep.STABILIZING;
END_IF;

IF ResetEdge.Q THEN
    SavedState := E_CycleStep.X0_PREPARATION;
    IF State = E_CycleStep.STABILIZING THEN
        State := E_CycleStep.X0_PREPARATION;
    END_IF;
END_IF;

// Gestion de l'Abandon explicite
IF AbortEdge.Q THEN
    State := E_CycleStep.X0_PREPARATION;
    WaitingResume := FALSE;
    PausedState := E_CycleStep.X0_PREPARATION;
END_IF;
{endregion}

{region "§3 Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
CASE State OF

    E_CycleStep.X0_PREPARATION:
        CycleStep := E_CycleStep.X0_PREPARATION;
        CycleStateStr := 'X0 - Verification coherence systeme';
        WinchM1Cmd.StartStop := FALSE; WinchM1Cmd.Direction := 0; WinchM1Cmd.SpeedPct := 0.0;
        WinchM2Cmd.StartStop := FALSE; WinchM2Cmd.Direction := 0; WinchM2Cmd.SpeedPct := 0.0;
        TranslationCmd.Start := FALSE; TranslationCmd.Target := 0;
        BucketCmd.Open := FALSE; BucketCmd.Close := FALSE; BucketCmd.KoboldContactorCmd := FALSE;
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0400;
        OperatorAction := 'Demander le demarrage du cycle (Bouton IHM ou armement Homme-Mort).';

        // Transition si système sain et réarmé (front reset ou démarrage).
        // 🔫 D2 : démarrage par bouton IHM (StartEdge) OU armement homme-mort joystick
        IF (StartEdge.Q OR DeadmanArmedEdge.Q) AND NOT Fault.Error THEN
            WaitingResume := FALSE;
            State := E_CycleStep.X1_HOMING;
        END_IF;

    E_CycleStep.X1_HOMING:
        CycleStep := E_CycleStep.X1_HOMING;
        CycleStateStr := 'X1 - Referencement codeurs (vitesses lentes)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0401;
        OperatorAction := 'Maintenir la montee lente vers les capteurs de referencement.';

        // Vitesses lentes pour chercher capteur top + référencement
        IF NOT HomedM1 OR NOT HomedM2 THEN
            WinchM1Cmd.StartStop := CycleMotionPermit;
            WinchM1Cmd.Direction := 1;   // montée lente vers capteur top
            WinchM1Cmd.SpeedPct := 10.0;
            WinchM2Cmd.StartStop := CycleMotionPermit;
            WinchM2Cmd.Direction := 1;
            WinchM2Cmd.SpeedPct := 10.0;
            IF HomingRequest THEN
                State := E_CycleStep.X2_WORK_POS_SELECT;
            END_IF;
        ELSE
            // déjà homé → passe vite
            State := E_CycleStep.X2_WORK_POS_SELECT;
        END_IF;

    E_CycleStep.X2_WORK_POS_SELECT:
        CycleStep := E_CycleStep.X2_WORK_POS_SELECT;
        CycleStateStr := 'X2 - Selection position travail';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := 0;
        WaitingForOperator := (SelTarget = 0) OR NOT CycleMotionPermit;
        WaitingForProcess := (SelTarget <> 0) AND CycleMotionPermit;
        OperatorActionId := 16#0402;
        OperatorAction := 'Selectionner la cible et maintenir la translation vers la position de travail.';

        IF (SelTarget = 1) OR (SelTarget = 3) OR (SelTarget = 4) THEN
            SelectedWorkTarget := SelTarget;
            TranslationCmd.Target := SelTarget;
            TranslationCmd.Start := CycleMotionPermit;
            // Arrivée à la cible (Trémie/P1/Maintenance)
            IF CycleMotionPermit AND (
                (SelTarget = 1 AND Translation_At_Tremie) OR
                (SelTarget = 3 AND Translation_At_P1) OR
                (SelTarget = 4 AND Translation_At_Maintenance)) THEN
                TranslationCmd.Start := FALSE;
                State := E_CycleStep.X3_OPEN_BUCKET;
            END_IF;
        END_IF;

    E_CycleStep.X3_OPEN_BUCKET:
        CycleStep := E_CycleStep.X3_OPEN_BUCKET;
        CycleStateStr := 'X3 - Ouverture benne';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 0;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0403;
        OperatorAction := 'Maintenir le joystick : ouverture complete de la benne.';

        IF Benne_IsOpen THEN
            State := E_CycleStep.X4_DESCEND_OPEN;
        ELSE
            BucketCmd.Open := CycleMotionPermit;
            IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.Open := FALSE;
                State := E_CycleStep.X4_DESCEND_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.X4_DESCEND_OPEN:
        CycleStep := E_CycleStep.X4_DESCEND_OPEN;
        CycleStateStr := 'X4 - Plongee benne ouverte (synchro)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0404;
        OperatorAction := 'Maintenir la descente : plongee synchro et detection fond Kobold.';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := -1;
        WinchM1Cmd.SpeedPct  := 50.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := -1;
        WinchM2Cmd.SpeedPct  := 50.0;
        BucketCmd.KoboldContactorCmd := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM;
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.X5_BOTTOM_CONFIRMED;
        END_IF;

    E_CycleStep.X5_BOTTOM_CONFIRMED:
        CycleStep := E_CycleStep.X5_BOTTOM_CONFIRMED;
        CycleStateStr := 'X5 - Fond confirme : remontee securisee';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0405;
        OperatorAction := 'Fond confirme : maintenir la montee jusqu a la hauteur de fermeture.';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct := 20.0;

        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X6_CLOSE_BUCKET;
        END_IF;

    E_CycleStep.X6_CLOSE_BUCKET:
        CycleStep := E_CycleStep.X6_CLOSE_BUCKET;
        CycleStateStr := 'X6 - Fermeture benne (tolerance a peu pres ferme)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0406;
        OperatorAction := 'Maintenir la commande : fermeture de la benne.';

        WinchM1Cmd.StartStop := FALSE;
        BucketCmd.Close := TRUE;

        IF CycleMotionPermit AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.Close := FALSE;
            State := E_CycleStep.X7_CTRL_ASCENT;
        END_IF;

    E_CycleStep.X7_CTRL_ASCENT:
        CycleStep := E_CycleStep.X7_CTRL_ASCENT;
        CycleStateStr := 'X7 - Remontee lente de controle';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0407;
        OperatorAction := 'Maintenir la montee lente : palier de controle et synchronisme.';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        IF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.X8_ASCENT_LOADED;
        END_IF;

    E_CycleStep.X8_ASCENT_LOADED:
        CycleStep := E_CycleStep.X8_ASCENT_LOADED;
        CycleStateStr := 'X8 - Remontee en charge';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#0408;
        OperatorAction := 'Maintenir la montee en charge jusqu a la limite haute.';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 70.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 70.0;

        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X9_DRAIN_PAUSE;
        END_IF;

    E_CycleStep.X9_DRAIN_PAUSE:
        CycleStep := E_CycleStep.X9_DRAIN_PAUSE;
        CycleStateStr := 'X9 - Egouttage du godet en cours';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.NONE;
        ExpectedDirection := 0;
        WaitingForOperator := FALSE;
        WaitingForProcess := TRUE;
        OperatorActionId := 16#0409;
        OperatorAction := 'Egouttage du godet en cours (temporisation).';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.X10_TRANSLATE_DUMP;
        END_IF;

    E_CycleStep.X10_TRANSLATE_DUMP:
        CycleStep := E_CycleStep.X10_TRANSLATE_DUMP;
        CycleStateStr := 'X10 - Deplacement vers tremie (grille/crible libres)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := -1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#040A;
        OperatorAction := 'Maintenir la translation vers la tremie de dechargement.';

        TranslationCmd.Target := 1; // Trémie
        TranslationCmd.Start := CycleMotionPermit;

        IF CycleMotionPermit AND Translation_At_Tremie THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.X11_OPEN_DUMP;
        END_IF;

    E_CycleStep.X11_OPEN_DUMP:
        CycleStep := E_CycleStep.X11_OPEN_DUMP;
        CycleStateStr := 'X11 - Vidange / ouverture du godet (montee possible, descente ouvre)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT CycleMotionPermit;
        WaitingForProcess := CycleMotionPermit;
        OperatorActionId := 16#040B;
        OperatorAction := 'Deflechir vers le bas pour ouvrir la benne et vider la charge.';

        WinchM1Cmd.StartStop := CycleMotionPermit AND (WinchM1Cmd.Direction = 1);
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit AND (WinchM2Cmd.Direction = 1);
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        BucketCmd.Open := CycleMotionPermit AND (WinchM1Cmd.Direction = -1);

        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.Open := FALSE;
            State := E_CycleStep.X13_DONE_SYNC;
        END_IF;

    E_CycleStep.X13_DONE_SYNC:
        CycleStep := E_CycleStep.X13_DONE_SYNC;
        CycleStateStr := 'X13 - Cycle automatique complete - pret';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        Lifecycle.Done := TRUE;
        Lifecycle.Busy := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#040D;
        OperatorAction := 'Cycle termine avec succes. Relancer un nouveau cycle.';

        // Compteur de prélèvements (RETAIN)
        SampleCount := SampleCount + 1;

        IF StartEdge.Q THEN
            Lifecycle.Done := FALSE;
            State := E_CycleStep.X0_PREPARATION;
        END_IF;

    E_CycleStep.STABILIZING:
        CycleStep := E_CycleStep.STABILIZING;
        CycleStateStr := 'X14 - Cycle en attente / stabilisation (STAB)';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        BucketCmd.Open := FALSE;
        BucketCmd.Close := FALSE;
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0480;
        OperatorAction := 'Cycle stabilise sur anomalie : acquitter le defaut pour reinitialiser.';

END_CASE;
{endregion}

{region "§4 Repli homme mort & Syntheses"}
// 🛑 Relâchement du manche (retour au centre) : neutralisation des demandes actives
IF Lifecycle.Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.StartStop := FALSE;
    WinchM2Cmd.StartStop := FALSE;
    TranslationCmd.Start := FALSE;
    BucketCmd.Open := FALSE;
    BucketCmd.Close := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;
END_IF;

RequestActive := WinchM1Cmd.StartStop OR WinchM2Cmd.StartStop OR TranslationCmd.Start OR BucketCmd.Open OR BucketCmd.Close;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
KoboldRiseEdge(CLK := KoboldImmersed);
KoboldFallEdge(CLK := KoboldImmersed);

// Base de temps nulle = timers de garde inoperants : defaut de parametrage inconditionnel.
ErrorCausePresent := (CycleTime <= T#0ms)
                  OR (NOT BypassPreconditions AND ((DiveStartMin_M < ImmersionUpper_M)
                       OR (ImmersionUpper_M <= ImmersionLower_M)
                       OR (ImmersionLower_M <= LimitLegalDepthMin_M)
                       OR (CableLimitAscent_M <= ImmersionLower_M)));

// ⏱️ Plafonds anti-blocage calcules au runtime : course credible max / vitesse Palier 1 mini x marge.
// Course immersion = du plafond haut d'exploitation a la borne basse d'immersion (depart de plongee
// possible n'importe ou entre DiveStartMin_M et CableLimitAscent_M -> on prend la borne la plus large).
// Course bornee [plancher .. plafond] avant conversion REAL->UDINT->TIME : une valeur IHM
// aberrante ne peut pas provoquer d'overflow silencieux sur le timeout de garde (CQS §6).
ImmersionCourse_M   := LIMIT(CST_TimeoutMinCourse_M, CableLimitAscent_M - ImmersionLower_M, CST_TimeoutMaxCourse_M);
BottomCourse_M      := LIMIT(CST_TimeoutMinCourse_M, ImmersionLower_M - LimitLegalDepthMin_M, CST_TimeoutMaxCourse_M);
CalculatedImmersionTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    ImmersionCourse_M / CST_DiveSpeedMin_Mps * CST_TimeoutMarginFactor * CST_SecToMs));
CalculatedBottomTimeout    := UDINT_TO_TIME(REAL_TO_UDINT(
    BottomCourse_M / CST_DiveSpeedMin_Mps * CST_TimeoutMarginFactor * CST_SecToMs));

// ⏱️ Intégrateurs de temps de mouvement effectif (D1 anti-pompage)
IF (DiveState = E_DiveSearchState.SEARCHING_IMMERSION) AND MotionRequestActive AND (MotionDirection = -1) THEN
    ImmersionTimerAcc := ImmersionTimerAcc + CycleTime;
    IF ImmersionTimerAcc >= CalculatedImmersionTimeout THEN
        TimeoutImmersionFault := TRUE;
    END_IF;
END_IF;

IF (DiveState = E_DiveSearchState.SEARCHING_BOTTOM) AND MotionRequestActive AND (MotionDirection = -1) THEN
    BottomTimerAcc := BottomTimerAcc + CycleTime;
    IF BottomTimerAcc >= CalculatedBottomTimeout THEN
        TimeoutBottomFault := TRUE;
    END_IF;
END_IF;

IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT KoboldImmersed AND NOT MotionRequestActive AND NOT (CurrentSpeedStep > 4) THEN
    SeqErrorFault         := FALSE;
    Palier5ForbiddenFault := FALSE;
    TimeoutImmersionFault := FALSE;
    TimeoutBottomFault    := FALSE;
    ImmersionTimerAcc     := T#0ms;
    BottomTimerAcc        := T#0ms;
    ImmersionConfirmed    := FALSE;
    BottomTouchConfirmed  := FALSE;
    StepAtFaultCaptured   := FALSE;
    DiveState             := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;

instCauses[0].Active   := SeqErrorFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Incoherence sequence immersion Kobold';

instCauses[2].Active   := ErrorCausePresent;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Parametrage invalide des seuils de plongee';

instCauses[3].Active   := Palier5ForbiddenFault;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Mesure Kobold impossible : vitesse trop elevee (Palier 5 interdit)';

instCauses[4].Active   := TimeoutImmersionFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement tempo recherche immersion Kobold';

instCauses[5].Active   := TimeoutBottomFault;
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Depassement tempo recherche fond Kobold';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// 📸 Capture ordonnée de StepAtFault (D2). Les défauts levés dans le CASE se figent au site du
// latch (voir §3) ; ce bloc ne couvre que les défauts détectés en §1 (timeouts, paramétrage),
// où DiveState/PrevState sont encore l'étape réelle. StepAtFaultCaptured évite l'écrasement.
ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT KoboldImmersed AND NOT MotionRequestActive AND NOT (CurrentSpeedStep > 4) THEN
    StepAtFault := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    DescendPermit := FALSE;
    KoboldMeasureEnable := FALSE;
    KoboldContactorCmd := FALSE;
    BottomTouchConfirmed := FALSE;
    DiveState := E_DiveSearchState.WAIT_PRECONDITIONS;
    // StepAtFault / StepAtFaultCaptured NON reinitialises ici : l'etape figee au defaut reste
    // lisible pour l'IHM/diagnostic apres un cycle Enable OFF->ON ; seul un front Reset l'efface.
    OperatorActionId := 0;
    OperatorAction := '';
    ImmersionConfirmed := FALSE;
    ImmersionTimerAcc := T#0ms;
    BottomTimerAcc := T#0ms;
    MinStepDown := 0;
    PrevState := E_DiveSearchState.WAIT_PRECONDITIONS;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Machine etat plongee recherche fond"}
DescendPermit := FALSE;
KoboldMeasureEnable := FALSE;
KoboldContactorCmd := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;

// Descente reellement demandee ET sans cause de coupure immediate : anti-chauffe contacteur Kobold
// (H1 : jamais alimente hors descente active), coupure meme-scan sur Palier 5 interdit et incoherence
// sequence (H2), et double garde sur le mode maintenance (H5, en plus du gate Enable de PRG_03).
DescentActive := MotionRequestActive AND (MotionDirection = -1)
             AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
             AND NOT (CurrentSpeedStep > 4)
             AND NOT SeqErrorFault;

// Garde-fou non-redemarrage auto : un defaut latche non acquitte verrouille la machine
// d'etat en ERROR_HOLD, meme si la vue live Fault.Error retombe (cause disparue).
IF Fault.Error OR Fault.Latched THEN
    DiveState := E_DiveSearchState.ERROR_HOLD;
    KoboldContactorCmd := FALSE;
    OperatorActionId := 16#0180;
    OperatorAction := 'Vérifier les conditions puis réarmer avant une nouvelle plongée.';
ELSE
    CASE DiveState OF
        E_DiveSearchState.WAIT_PRECONDITIONS:
            KoboldContactorCmd := FALSE;
            IF NOT BypassPreconditions
               AND (NOT BucketIsOpen OR NOT PositionsValid OR KoboldImmersed
                    OR (M1Position_M < DiveStartMin_M) OR (M2Position_M < DiveStartMin_M)) THEN
                OperatorActionId := 16#0100;
                OperatorAction := 'Vérifier les conditions initiales de plongée.';
            ELSE
                DiveState := E_DiveSearchState.READY_TO_DESCEND;
            END_IF;

        E_DiveSearchState.READY_TO_DESCEND:
            Ready := TRUE;
            KoboldContactorCmd := FALSE;
            OperatorActionId := 16#0101;
            OperatorAction := 'Demander une descente pour rechercher le fond.';
            IF MotionRequestActive AND (MotionDirection = -1) THEN
                ImmersionTimerAcc := T#0ms; // ⏱️ RAZ à l'entrée exacte de SEARCHING_IMMERSION
                DiveState := E_DiveSearchState.SEARCHING_IMMERSION;
            END_IF;

        E_DiveSearchState.SEARCHING_IMMERSION:
            Lifecycle.Busy := TRUE;
            DescendPermit := DescentActive;
            KoboldMeasureEnable := DescentActive;
            KoboldContactorCmd := DescentActive; // Alimentation contacteur uniquement sous descente active (anti-chauffe)
            OperatorActionId := 16#0102;
            OperatorAction := 'Maintenir la descente : recherche immersion Kobold.';

            // 🛑 Interdiction du Palier 5 pendant la détection Kobold
            IF (CurrentSpeedStep > 4) AND NOT StepAtFaultCaptured THEN
                StepAtFault := DiveState;          // fige l'etape reelle avant tout basculement
                StepAtFaultCaptured := TRUE;
            END_IF;
            IF CurrentSpeedStep > 4 THEN
                Palier5ForbiddenFault := TRUE;
            END_IF;

            IF KoboldRiseEdge.Q THEN
                IF (M1Position_M <= ImmersionUpper_M) AND (M1Position_M >= ImmersionLower_M)
                   AND (M2Position_M <= ImmersionUpper_M) AND (M2Position_M >= ImmersionLower_M) THEN
                    ImmersionConfirmed := TRUE;
                    BottomTimerAcc := T#0ms; // ⏱️ RAZ à l'entrée exacte de SEARCHING_BOTTOM
                    DiveState := E_DiveSearchState.SEARCHING_BOTTOM;
                ELSE
                    IF NOT StepAtFaultCaptured THEN
                        StepAtFault := DiveState;
                        StepAtFaultCaptured := TRUE;
                    END_IF;
                    SeqErrorFault := TRUE;
                END_IF;
            ELSIF (M1Position_M < ImmersionLower_M) OR (M2Position_M < ImmersionLower_M) THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := DiveState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SeqErrorFault := TRUE;
            END_IF;

        E_DiveSearchState.SEARCHING_BOTTOM:
            Lifecycle.Busy := TRUE;
            DescendPermit := DescentActive;
            KoboldMeasureEnable := DescentActive;
            KoboldContactorCmd := DescentActive; // Alimentation uniquement sous descente active (anti-chauffe)
            OperatorActionId := 16#0103;
            OperatorAction := 'Maintenir la descente : immersion validée, recherche du fond.';

            // 🛑 Interdiction du Palier 5 pendant la détection Kobold
            IF (CurrentSpeedStep > 4) AND NOT StepAtFaultCaptured THEN
                StepAtFault := DiveState;
                StepAtFaultCaptured := TRUE;
            END_IF;
            IF CurrentSpeedStep > 4 THEN
                Palier5ForbiddenFault := TRUE;
            END_IF;

            IF KoboldFallEdge.Q AND ImmersionConfirmed THEN
                BottomTouchConfirmed := TRUE;
                ImmersionConfirmed := FALSE;
                KoboldContactorCmd := FALSE; // Coupure immédiate à la détection pour éviter surchauffe
                DiveState := E_DiveSearchState.BOTTOM_CONFIRMED;
            END_IF;

        E_DiveSearchState.BOTTOM_CONFIRMED:
            Lifecycle.Done := TRUE;
            KoboldContactorCmd := FALSE; // Coupure anti-chauffe
            OperatorActionId := 16#0104;
            OperatorAction := 'Fond détecté : demander la fermeture ou l extraction.';

        E_DiveSearchState.ERROR_HOLD:
            KoboldContactorCmd := FALSE;
    END_CASE;
END_IF;

// 🤿 Plancher de palier en descente impose pendant la plongee.
// Actif uniquement en phase de recherche (immersion/fond) ET sous descente reellement
// demandee (DescentActive) : retombe a 0 au front de sortie de plongee (BOTTOM_CONFIRMED /
// ERROR_HOLD / WAIT_PRECONDITIONS), donc aucun plancher residuel. Ne cree jamais de mouvement
// par lui-meme : il ne fait que majorer le palier d'une descente deja demandee et permise.
IF DescentActive AND (DiveState = E_DiveSearchState.SEARCHING_IMMERSION
                  OR DiveState = E_DiveSearchState.SEARCHING_BOTTOM) THEN
    MinStepDown := CfgDiveFloorStep;
ELSE
    MinStepDown := 0;
END_IF;

// 💾 Mémorisation de l'étape précédente en toute fin de scan
PrevState := DiveState;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
// Parametrage invalide : distance nulle, backstop nul, base de temps nulle, ou backstop
// qui fauterait AVANT le watchdog benne (masquerait BucketError - ordre des watchdogs).
ErrorCausePresent := (ControlAscentDistance_M <= 0.0)
                  OR (CfgBucketCloseTimeout <= T#0ms)
                  OR (CycleTime <= T#0ms)
                  OR (CfgBucketCloseTimeout <= BucketMoveTimeout)
                  OR (CfgBucketCloseTimeout > CST_BackstopMax);  // borne haute : evite l'overflow de BucketCloseTimerAcc (F3)

// ⏱️ Plafond anti-blocage decollage calcule au runtime : course de controle bornee [plancher..plafond]
// avant conversion REAL->UDINT->TIME (anti-overflow sur valeur IHM aberrante, CQS §6).
CalculatedControlAscentTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    LIMIT(CST_TimeoutMinDistance_M, ControlAscentDistance_M, CST_TimeoutMaxDistance_M)
    / CST_MinSpeed_Mps * CST_ControlAscentMargin * CST_SecToMs));

// ⏱️ Integrateurs de temps de montee effective (anti-pompage homme-mort)
IF (ExtractionState = E_ExtractionSequenceState.CLOSING_BUCKET) AND MotionRequestActive AND (MotionDirection = 1) THEN
    BucketCloseTimerAcc := BucketCloseTimerAcc + CycleTime;
    IF BucketCloseTimerAcc >= CfgBucketCloseTimeout THEN
        TimeoutBucketCloseFault := TRUE;
    END_IF;
END_IF;

IF (ExtractionState = E_ExtractionSequenceState.CONTROL_ASCENT) AND MotionRequestActive AND (MotionDirection = 1) THEN
    ControlAscentTimerAcc := ControlAscentTimerAcc + CycleTime;
    IF ControlAscentTimerAcc >= CalculatedControlAscentTimeout THEN
        TimeoutControlAscentFault := TRUE;
    END_IF;
END_IF;

// Etat physique des causes treuil/benne : conditionne l'acquittement des latches a cause persistante (F2).
CausesPhysiquesEffacees := NOT BucketError AND NOT WinchSyncError
                        AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    // Latches sans cause physique persistante (timeouts, backstop) : acquittables sur simple front Reset.
    TimeoutBucketCloseFault   := FALSE;
    TimeoutControlAscentFault := FALSE;
    BucketCloseTimerAcc       := T#0ms;
    ControlAscentTimerAcc     := T#0ms;
    StepAtFaultCaptured       := FALSE;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    // Latches de cause physique : acquittables SEULEMENT si l'entree de defaut est revenue saine (F2).
    IF CausesPhysiquesEffacees THEN
        BucketErrorFault      := FALSE;
        SyncOrSpeedErrorFault := FALSE;
    END_IF;
END_IF;

instCauses[1].Active   := BucketErrorFault;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Defaut sous-systeme benne pendant fermeture';

instCauses[2].Active   := SyncOrSpeedErrorFault;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Defaut synchro ou capteurs treuils pendant remontee';

instCauses[3].Active   := ErrorCausePresent;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Parametrage distance de controle ou backstop invalide';

instCauses[4].Active   := TimeoutBucketCloseFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement backstop fermeture benne';

instCauses[5].Active   := TimeoutControlAscentFault;
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Depassement tempo decollage controle';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// 📸 Capture ordonnee de StepAtFault (D2). Les defauts leves dans le CASE se figent au site du
// latch (voir §3) ; ce bloc ne couvre que les defauts detectes en §1 (backstop, timeout, parametrage),
// ou ExtractionState/PrevState sont encore l'etape reelle. StepAtFaultCaptured evite l'ecrasement.
ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    StepAtFault := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    BucketCloseRequest := FALSE;
    AscentPermit := FALSE;
    ExtractionControlActive := FALSE;
    BottomConfirmationConsumed := FALSE;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    // StepAtFault / StepAtFaultCaptured NON reinitialises ici : l'etape figee au defaut reste
    // lisible pour l'IHM/diagnostic apres un cycle Enable OFF->ON ; seul un front Reset l'efface.
    PrevState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    BucketCloseTimerAcc := T#0ms;
    ControlAscentTimerAcc := T#0ms;
    OperatorActionId := 0;
    OperatorAction := '';
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Machine etat fermeture remontee"}
BucketCloseRequest := FALSE;
AscentPermit := FALSE;
ExtractionControlActive := FALSE;
BottomConfirmationConsumed := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;

// Montee assistee reellement demandee : sens montee + mode maintenance (H5, double garde vs Enable PRG_03).
AssistPermit := MotionRequestActive AND (MotionDirection = 1)
            AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2);
// Entrees [SAFE] saines : coupure meme-scan des permis si defaut treuil/synchro (H2), avant meme le latch.
AscentControlSafe := NOT WinchSyncError AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
AscentNominalSafe := NOT WinchSyncError AND PositionsValid;

// Garde-fou non-redemarrage auto : un defaut latche non acquitte verrouille la machine
// d'etat en ERROR_HOLD, meme si la vue live Fault.Error retombe (cause disparue).
IF Fault.Error OR Fault.Latched THEN
    ExtractionState := E_ExtractionSequenceState.ERROR_HOLD;
    OperatorActionId := 16#0280;
    OperatorAction := 'Vérifier la benne et les treuils puis réarmer avant de reprendre.';
ELSE
    CASE ExtractionState OF
        E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION:
            IF BottomPositionConfirmed THEN
                ExtractionState := E_ExtractionSequenceState.READY_TO_CLOSE;
            ELSE
                OperatorActionId := 16#0200;
                OperatorAction := 'Confirmer que la benne est posée au fond avant extraction.';
            END_IF;

        E_ExtractionSequenceState.READY_TO_CLOSE:
            Ready := TRUE;
            OperatorActionId := 16#0201;
            OperatorAction := 'Demander la montée pour fermer la benne.';
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                BottomConfirmationConsumed := TRUE;
                BucketCloseTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CLOSING_BUCKET
                ExtractionState := E_ExtractionSequenceState.CLOSING_BUCKET;
            END_IF;

        E_ExtractionSequenceState.CLOSING_BUCKET:
            Lifecycle.Busy := TRUE;
            BucketCloseRequest := AssistPermit AND NOT BucketError; // coupure meme-scan sur defaut benne (H2)
            OperatorActionId := 16#0202;
            OperatorAction := 'Maintenir la montée : fermeture de la benne en cours.';
            IF BucketError THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                BucketErrorFault := TRUE;
            ELSIF BucketIsClosed AND NOT BucketBusy THEN
                ControlStartM1Position_M := M1Position_M;
                ControlStartM2Position_M := M2Position_M;
                ControlAscentTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CONTROL_ASCENT
                ExtractionState := E_ExtractionSequenceState.CONTROL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.CONTROL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentControlSafe; // coupure meme-scan sur defaut synchro/capteurs (H2)
            ExtractionControlActive := AscentPermit;            // plafond palier 1 suit le permis de montee
            OperatorActionId := 16#0203;
            OperatorAction := 'Maintenir la montée : contrôle charge au palier minimal.';
            IF NOT AscentControlSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            ELSIF (M1Position_M >= (ControlStartM1Position_M + ControlAscentDistance_M))
               AND (M2Position_M >= (ControlStartM2Position_M + ControlAscentDistance_M)) THEN
                ExtractionState := E_ExtractionSequenceState.NOMINAL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.NOMINAL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentNominalSafe; // coupure meme-scan sur defaut synchro/position (H2)
            OperatorActionId := 16#0204;
            OperatorAction := 'Maintenir la montée : extraction en cours.';
            IF NOT AscentNominalSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            END_IF;

        E_ExtractionSequenceState.ERROR_HOLD:
            ;
    END_CASE;
END_IF;

// 💾 Memorisation de la phase precedente en toute fin de scan (capture StepAtFault fiable)
PrevState := ExtractionState;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    SemiAutoRefusedFault  := FALSE;
    SemiAutoRefusedHoming := FALSE;
END_IF;

// 🔑 1bis. RESTAURATION BOOT DES DRAPEAUX PERSISTANTS
// Non-RETAIN -> réinitialisé à chaque warm/cold reset ; relu depuis GVL_PERSISTENT (miroir
// réécrit chaque scan par PRG_03). Aucune perte du re-homing obligatoire sur coupure.
IF NOT FirstScanDone THEN
    FirstScanDone         := TRUE;
    MaintHomingRequiredM1 := BootHomingRequiredM1;
    MaintHomingRequiredM2 := BootHomingRequiredM2;
    PrevArbitratedMode    := E_Mode.DISABLE;
END_IF;

// 🔑 1ter. RE-HOMING OBLIGATOIRE — ARMEMENT IMMÉDIAT (AF-05 §4bis)
// Armé AVANT l'arbitrage de mode (§3) et non à la sortie du mode maintenance :
//   1. pas de fenêtre d'un scan où SEMI_AUTO serait arbitré malgré un re-homing requis ;
//   2. pas de perte de l'obligation sur coupure / download pendant la maintenance
//      (la valeur est écrite dans le miroir PERSISTENT dès le scan courant, pas à la sortie).
IF M1PositionLimitOverridden THEN
    MaintHomingRequiredM1 := TRUE;
END_IF;
IF M2PositionLimitOverridden THEN
    MaintHomingRequiredM2 := TRUE;
END_IF;

// Levée : UNIQUEMENT sur cycle de homing complet réussi (Done + Homed + non suspect).
IF MaintHomingRequiredM1 AND M1HomingDone AND M1Homed AND NOT M1HomingSuspect THEN
    MaintHomingRequiredM1 := FALSE;
END_IF;
IF MaintHomingRequiredM2 AND M2HomingDone AND M2Homed AND NOT M2HomingSuspect THEN
    MaintHomingRequiredM2 := FALSE;
END_IF;

// Refus semi-auto — une cause = un fait (AF03 §4) : défaut codeur et re-homing sont distincts.
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    SemiAutoRefusedFault := TRUE;
END_IF;
IF (SelMode = E_Mode.SEMI_AUTO) AND (MaintHomingRequiredM1 OR MaintHomingRequiredM2) THEN
    SemiAutoRefusedHoming := TRUE;
END_IF;
SemiAutoRefusedReference := (SelMode = E_Mode.SEMI_AUTO) AND NOT MachineReferenceReady;

instCauses[0].Active   := SemiAutoRefusedFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Mode Semi-Auto refuse car defaut codeur present';

instCauses[2].Active   := SemiAutoRefusedHoming;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Mode Semi-Auto refuse car re-homing obligatoire (depassement de limite de position)';

instCauses[3].Active   := SemiAutoRefusedReference;
instCauses[3].Latching := FALSE;
instCauses[3].Texte    := 'Mode Semi-Auto refuse : referencement M1/M2/benne incomplet';

// Cause 1 — changement de mode refusé : treuils non à l'arrêt mécanique confirmé.
// Non latchée (live) : l'information disparaît dès que la condition redevient vraie, sans
// acquittement — c'est une consigne d'action IHM (« arrêter les treuils »), pas un défaut machine.
// 📌 Lag 1 scan assumé : la cause est évaluée avant l'arbitrage §3 du cycle courant.
instCauses[1].Active   := Auth.ModeChangePendingBlocked;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Changement de mode refuse : arreter les treuils avant de changer de mode';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation si désactivé ou AU non armé
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Auth.Mode := E_Mode.DISABLE;
    Auth.SyncEnable := TRUE;
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal par défaut
    Auth.MaintenanceM3TargetEnable := FALSE;
    // Faits persistants : PUBLIÉS même neutralisé (l'IHM doit continuer à voir
    // qu'un re-homing est requis tant que la machine n'est pas réarmée). Aucune autorisation
    // n'est accordée ici : Auth.Mode := DISABLE verrouille tout le reste.
    Auth.ModeChangePendingBlocked := FALSE;
    Auth.HomingRequiredM1 := MaintHomingRequiredM1;
    Auth.HomingRequiredM2 := MaintHomingRequiredM2;
    PrevArbitratedMode := Auth.Mode;
    Ready := FALSE;
    PrevInhibitM1 := FALSE;
    PrevInhibitM2 := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage du mode"}
// ⚙️ 3. ARBITRAGE DU MODE

// 3.1 ARRÊT MÉCANIQUE CONFIRMÉ DES DEUX TREUILS (condition de bascule, AF-05 §4bis)
// Même composite que l'armement Méca B : contacteurs retombés + frein serré, redondé par
// la mesure absolue de vitesse. Vaut pour les DEUX treuils (M1 ET M2).
ModeChangeAllowed := M1ContactorsReleased AND NOT M1BrakeIsOpen
                     AND (ABS(M1SpeedAbsMps) < MovementSpeedThresholdMps)
                     AND M2ContactorsReleased AND NOT M2BrakeIsOpen
                     AND (ABS(M2SpeedAbsMps) < MovementSpeedThresholdMps);

// 3.2 ARBITRAGE — priorité du refus de sécurité, puis du refus de bascule
IF (SelMode = E_Mode.SEMI_AUTO)
   AND (EncoderFaultPresent OR MaintHomingRequiredM1 OR MaintHomingRequiredM2 OR NOT MachineReferenceReady) THEN
    // Défaut codeur ou re-homing obligatoire : SEMI_AUTO interdit, repli MAINT_N1.
    Auth.Mode := E_Mode.MAINT_N1;
    Auth.ModeChangePendingBlocked := FALSE;
ELSIF (SelMode <> PrevArbitratedMode)
      AND (SelMode <> E_Mode.DISABLE) AND (PrevArbitratedMode <> E_Mode.DISABLE)
      AND NOT ModeChangeAllowed THEN
    // Bascule N1/N2/SEMI_AUTO refusée : le mode courant est MAINTENU.
    // ⚠️ Exception de sécurité (contrat D2) : une transition vers ou depuis DISABLE n'est
    // JAMAIS bloquée — sortir d'un mode maintenance ne doit jamais dépendre d'un treuil à l'arrêt.
    Auth.Mode := PrevArbitratedMode;
    Auth.ModeChangePendingBlocked := TRUE;
ELSE
    Auth.Mode := SelMode;
    Auth.ModeChangePendingBlocked := FALSE;
END_IF;

PrevArbitratedMode := Auth.Mode;
{endregion}

{region "§3bis Publication du re-homing obligatoire"}
// 🧭 3bis. PUBLICATION DU RE-HOMING OBLIGATOIRE
// Armement et levée réalisés en §1ter, AVANT l'arbitrage de mode — voir le commentaire §1ter
// (pas de fenêtre d'un scan, pas de perte sur coupure en cours de maintenance).
Auth.HomingRequiredM1 := MaintHomingRequiredM1;
Auth.HomingRequiredM2 := MaintHomingRequiredM2;
{endregion}

{region "§4 Calcul autorisations machine"}
// 4. SYNC ENABLE — actionnable en MAINT_N1 ou MAINT_N2
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
Auth.SyncEnable := NOT ((Auth.Mode = E_Mode.MAINT_N1 OR Auth.Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 4bis. EXCLUSION MUTUELLE INHIBITIONS + RESET SYNC ENABLE
IF InhibitM1Request AND NOT PrevInhibitM1 THEN
    IF PrevInhibitM2 THEN
        Auth.InhibitM1 := FALSE;
    ELSE
        Auth.InhibitM1 := TRUE;
        Auth.InhibitM2 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSIF InhibitM2Request AND NOT PrevInhibitM2 THEN
    IF PrevInhibitM1 THEN
        Auth.InhibitM2 := FALSE;
    ELSE
        Auth.InhibitM2 := TRUE;
        Auth.InhibitM1 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSE
    IF InhibitM1Request AND InhibitM2Request THEN
        Auth.InhibitM1 := FALSE;
        Auth.InhibitM2 := FALSE;
    END_IF;
END_IF;

PrevInhibitM1 := InhibitM1Request;
PrevInhibitM2 := InhibitM2Request;

Auth.InhibitM1 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM1;
Auth.InhibitM2 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM2;

// 4ter. AUTORISATION ARRÊT HAUT (HomingApproach)
Auth.HomingApproachEnable := (Auth.Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 4quater. SÉLECTEUR JOYSTICK TREUIL
IF (Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1) THEN
    Auth.JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
ELSE
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal forcé
END_IF;

// 4quinquies. CIBLE TRANSLATION MAINTENANCE
Auth.MaintenanceM3TargetEnable := ((Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1)) AND SelMaintenanceZoneAccess;

// Re-vérification sécurité si sortie MAINT
IF (Auth.Mode <> E_Mode.MAINT_N2) AND (Auth.Mode <> E_Mode.MAINT_N1) THEN
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;
END_IF;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}
